"""Sieve-and-symbol evaluation of the count and harmonically weighted dials."""

from __future__ import annotations

import math
from typing import Dict, List, Sequence, Tuple


def primes_upto(limit: int) -> List[int]:
    """Sieve of Eratosthenes: all primes <= limit, in O(limit log log limit)."""
    if limit < 2:
        return []
    sieve = bytearray([1]) * (limit + 1)
    sieve[0] = sieve[1] = 0
    for p in range(2, int(limit**0.5) + 1):
        if sieve[p]:
            sieve[p * p :: p] = bytearray(len(sieve[p * p :: p]))
    return [i for i in range(limit + 1) if sieve[i]]


def jacobi(a: int, n: int) -> int:
    """Jacobi symbol (a|n) for odd n >= 1, by the binary algorithm.

    Cost O(log^2 n) bit operations: repeated removal of factors of two (sign
    rule from n mod 8) alternating with reciprocity swaps (sign flip exactly
    when both arguments are 3 mod 4).
    """
    if n <= 0 or n % 2 == 0:
        raise ValueError("Jacobi symbol requires an odd positive bottom argument")
    a %= n
    result = 1
    while a != 0:
        while a % 2 == 0:
            a //= 2
            if n % 8 in (3, 5):
                result = -result
        a, n = n, a
        if a % 4 == 3 and n % 4 == 3:
            result = -result
        a %= n
    return result if n == 1 else 0


def dials(N: int, cutoff: int) -> Tuple[int, float]:
    """Return (count dial, harmonically weighted dial) of N over primes <= cutoff.

    count dial     C(B) = #{l <= B : N is a quadratic residue mod l}
    weighted dial  W(B) = sum over those l of 1/l
    """
    count, weight = 0, 0.0
    for l in primes_upto(cutoff):
        if l == 2 or N % l == 0:
            continue
        if jacobi(N, l) == 1:
            count += 1
            weight += 1.0 / l
    return count, weight


def dial_sweep(N: int, cutoffs: Sequence[int]) -> Dict[int, Tuple[int, float]]:
    """Cumulative sweep: both dials at each cutoff, sharing one sieve."""
    ls = [l for l in primes_upto(max(cutoffs)) if l > 2]
    out: Dict[int, Tuple[int, float]] = {}
    count, weight, i = 0, 0.0, 0
    for B in sorted(cutoffs):
        while i < len(ls) and ls[i] <= B:
            l = ls[i]
            if N % l != 0 and jacobi(N, l) == 1:
                count += 1
                weight += 1.0 / l
            i += 1
        out[B] = (count, weight)
    return out

