"""Reciprocity-flip audit of a dial implementation."""


def twist(a: int, b: int) -> int:
    """The reciprocity twist character: -1 iff a = b = 3 (mod 4), else +1."""
    return -1 if (a % 4 == 3 and b % 4 == 3) else 1


def flip_audit(population: Sequence[int], moduli: Sequence[int]) -> Dict[str, float]:
    """Check 'the two dial forms differ exactly on l = N = 3 (mod 4)'.

    Every coprime row must satisfy (l|N) = twist(l,N) * (N|l); any violation is
    an implementation bug, not a finding. Returns the audit summary.
    """
    rows = cond_rows = cond_flips = uncond_flips = violations = 0
    for N in population:
        if N % 2 == 0:
            raise ValueError("population must consist of odd integers")
        for l in moduli:
            if math.gcd(l, N) != 1:
                continue
            clean, flipped = jacobi(N, l), jacobi(l, N)
            if flipped != twist(l, N) * clean:
                raise AssertionError(f"reciprocity violated at (N={N}, l={l})")
            flip = clean != flipped
            cond = (l % 4 == 3) and (N % 4 == 3)
            rows += 1
            cond_rows += cond
            cond_flips += flip and cond
            uncond_flips += flip
            violations += flip != cond
    return {
        "rows": rows,
        "condition_rate": cond_rows / rows if rows else 0.0,
        "conditional_flip_rate": cond_flips / cond_rows if cond_rows else 0.0,
        "unconditional_flip_rate": uncond_flips / rows if rows else 0.0,
        "violations": violations,
    }

