"""Flatness diagnostic for covariate weight design."""


def flatness(amplitudes: Sequence[float]) -> float:
    """flat(T) = (sum a)^2 / (|T| sum a^2), the exact multiplicative penalty
    incurred by weighting every observation equally instead of by amplitude.

    One pass, no target values required: this is a property of the covariate
    design alone. Values near 1 license counting; values near 0 mandate
    weighting.
    """
    n = len(amplitudes)
    if n == 0:
        return 0.0
    denominator = n * sum(x * x for x in amplitudes)
    return 0.0 if denominator == 0 else sum(amplitudes) ** 2 / denominator


def weighting_advice(amplitudes: Sequence[float]) -> str:
    f = flatness(amplitudes)
    if f > 0.9:
        return f"flatness {f:.3f}: profile nearly constant — counting costs < 10%."
    if f > 0.5:
        return f"flatness {f:.3f}: counting loses {100*(1-f):.0f}% — prefer weighting."
    return (f"flatness {f:.3f}: counting throws away {100*(1-f):.0f}% of the "
            f"attainable explained variance — weight by amplitude.")
